package ui

import (
	"embed"
	"io"
	"io/fs"
	"net/http"
	"strings"
)

// Built React console (vite → dist/). Regenerated by `npm run build` in /web.
//
//go:embed all:dist
var distFS embed.FS

// Handler serves the embedded SPA. API routes are registered separately and take precedence.
func Handler() http.Handler {
	sub, err := fs.Sub(distFS, "dist")
	if err != nil {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			http.Error(w, "ui embed missing: build web/", http.StatusServiceUnavailable)
		})
	}
	fileServer := http.FileServer(http.FS(sub))

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		// Never intercept API / health / static install trees (registered on mux first).
		if path != "/" && path != "/index.html" {
			// Try exact asset; if missing, SPA fallback for HashRouter is unnecessary
			// (hash routes stay on /). Still try file first.
			name := strings.TrimPrefix(path, "/")
			if f, err := sub.Open(name); err == nil {
				_ = f.Close()
				fileServer.ServeHTTP(w, r)
				return
			}
			// Unknown non-asset path → 404 (HashRouter only needs /)
			http.NotFound(w, r)
			return
		}
		f, err := sub.Open("index.html")
		if err != nil {
			http.Error(w, "index.html missing", http.StatusInternalServerError)
			return
		}
		defer f.Close()
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		stat, _ := f.Stat()
		if stat != nil {
			w.Header().Set("Content-Length", itoa(stat.Size()))
		}
		_, _ = io.Copy(w, f)
	})
}

func itoa(n int64) string {
	if n == 0 {
		return "0"
	}
	var b [20]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	return string(b[i:])
}
